extern alias Track1;extern alias Track2;using BenchmarkDotNet.Attributes;using BenchmarkDotNet.Configs;using BenchmarkDotNet.Order;using BenchmarkDotNet.Running;using ManagementBenchmarks;using System;using System.Net.Http;using System.Threading.Tasks;using T1=Track1::ManageSsisIntegrationRuntime.Track1Scenario;using T2=Track2::ManageSsisIntegrationRuntime.Track2Scenario;
namespace ManageSsisIntegrationRuntime.Benchmarks{[MemoryDiagnoser][Orderer(SummaryOrderPolicy.FastestToSlowest)][SimpleJob(launchCount:1,warmupCount:3,iterationCount:10,invocationCount:10)]public class IntegrationRuntimeBenchmarks{const string Sub="00000000-0000-0000-0000-000000000000";T1.Clients t1;Azure.ResourceManager.ArmClient t2;string endpoint;[GlobalSetup]public void Setup(){CpuTimeRecorder.Reset();endpoint=Environment.GetEnvironmentVariable("MOCK_ARM_ENDPOINT")??"http://127.0.0.1:5050";using(var h=new HttpClient()){var r=h.GetAsync(endpoint+"/__mock/health").GetAwaiter().GetResult();r.EnsureSuccessStatusCode();}t1=T1.CreateMockClient(endpoint,Sub);t2=T2.CreateMockClient(endpoint,Sub);}[Benchmark(Baseline=true,Description="Track 1 generated")]public Task Track1()=>CpuTimeRecorder.MeasureAsync(()=>T1.RunAsync(t1,Sub));[Benchmark(Description="Track 2 ARM")]public Task Track2()=>CpuTimeRecorder.MeasureAsync(()=>T2.RunAsync(t2,Sub));[GlobalCleanup]public void Report()=>CpuTimeRecorder.Report();}public static class Program{public static void Main(string[]a)=>BenchmarkRunner.Run<IntegrationRuntimeBenchmarks>(DefaultConfig.Instance.WithOptions(ConfigOptions.DisableOptimizationsValidator));}}
